package io.github.deepseekbridge;
import android.app.Application;import android.content.Context;import android.net.Uri;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.util.*;import java.util.zip.*;import javax.crypto.spec.SecretKeySpec;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={26,33},manifest=Config.NONE,application=Application.class)
public class ExtensionImportTest {
 Context context;ExtensionHub hub;
 @Before public void setup()throws Exception{context=RuntimeEnvironment.getApplication();LocalState vault=new LocalState(new EncryptedStateStore(new File(context.getCacheDir(),"import-"+UUID.randomUUID()+".enc"),new SecretKeySpec(new byte[32],"AES")));hub=new ExtensionHub(context,vault,(p,c)->{throw new IOException("Unexpected process start");},e->{});}
 @After public void cleanup(){hub.close();}
 @Test public void specialistSkillsInstallThroughTheRealNativeImportAndAreIdempotent()throws Exception {for(String kind:new String[]{"security","pentest","reverse"}){JSONObject snapshot=hub.builtinSkill(kind);String id=null;JSONArray plugins=snapshot.getJSONArray("plugins");for(int i=0;i<plugins.length();i++)if(kind.equals(plugins.getJSONObject(i).optString("builtin")))id=plugins.getJSONObject(i).getString("id");assertNotNull(id);assertTrue(hub.skill(id,"SKILL.md").getString("content").length()>100);assertEquals(plugins.length(),hub.builtinSkill(kind).getJSONArray("plugins").length());}assertEquals(3,hub.snapshot().getJSONArray("plugins").length());}
 @Test public void oneMarkdownFileNeedsNoPluginManifestAndItsPixelsAreNeverExecuted()throws Exception {File md=new File(context.getCacheDir(),"SKILL-"+UUID.randomUUID()+".md");Files.write(md.toPath(),"---\nname: review-fixture\ndescription: actual instructions\n---\n# Review\nRead source and cite evidence.".getBytes(StandardCharsets.UTF_8));JSONObject imported=ExtensionImports.fromUri(context,hub,Uri.fromFile(md)),plugin=imported.getJSONArray("plugins").getJSONObject(0);assertFalse(plugin.getBoolean("enabled"));assertEquals("review-fixture",plugin.getString("name"));assertEquals("SKILL.md",plugin.getJSONArray("skills").getJSONObject(0).getString("path"));String id=plugin.getString("id");hub.pluginToggle(id,true);assertTrue(hub.skill(id,"SKILL.md").getString("content").contains("cite evidence"));try{hub.skill(id,"studio-plugin.json");fail();}catch(IOException expected){}}
 @Test public void repositoryZipFindsNestedSkillsWithoutAHostSpecificManifest()throws Exception {File zip=new File(context.getCacheDir(),"skills-"+UUID.randomUUID()+".zip");try(ZipOutputStream out=new ZipOutputStream(new FileOutputStream(zip))){for(String[] file:new String[][]{{"repository-main/README.md","example"},{"repository-main/skills/review/SKILL.md","# Review\nLook for regressions."},{"repository-main/plugins/debug/SKILL.md","# Debug\nReproduce first."}}){out.putNextEntry(new ZipEntry(file[0]));out.write(file[1].getBytes(StandardCharsets.UTF_8));out.closeEntry();}}JSONObject plugin=hub.install(Uri.fromFile(zip)).getJSONArray("plugins").getJSONObject(0);assertEquals(2,plugin.getJSONArray("skills").length());String id=plugin.getString("id");hub.pluginToggle(id,true);assertTrue(hub.skill(id,"plugins/debug/SKILL.md").getString("content").contains("Reproduce"));}
 @Test public void builtInSkillEnablesInOneStepWithoutDuplicatesAndCanBeRemoved()throws Exception {JSONObject first=hub.builtinSkill("debug");String id=first.getJSONArray("plugins").getJSONObject(0).getString("id");assertTrue(first.getJSONArray("plugins").getJSONObject(0).getBoolean("enabled"));assertTrue(hub.skill(id,"SKILL.md").getString("content").contains("复现"));assertEquals(1,hub.builtinSkill("debug").getJSONArray("plugins").length());hub.pluginRemove(id);assertEquals(1,hub.builtinSkill("debug").getJSONArray("plugins").length());try{hub.builtinSkill("unknown");fail();}catch(IOException expected){}}
 @Test public void pastedMcpConfigIsValidatedAtomicallyAndCredentialsStayNative()throws Exception {JSONArray good=new JSONArray().put(new JSONObject().put("name","One").put("url","https://example.test/mcp").put("headers",new JSONObject().put("Authorization","Bearer fixture-private")).put("enabled",true));JSONArray bad=new JSONArray(good.toString()).put(new JSONObject().put("url","file:///invalid"));try{hub.importServers(bad);fail();}catch(Exception expected){}assertEquals(0,hub.snapshot().getJSONArray("servers").length());JSONObject saved=hub.importServers(good);assertEquals(1,saved.getJSONArray("servers").length());assertFalse(saved.toString().contains("fixture-private"));assertTrue(saved.getJSONArray("servers").getJSONObject(0).getBoolean("enabled"));}
 @Test public void plainMcpJsonImportsThroughTheSameFilePickerAndStartsDisabled()throws Exception{JSONObject value=ExtensionImports.fromText(context,hub,"","{\"mcpServers\":{\"docs\":{\"url\":\"https://example.test/mcp\"}}}");assertEquals(1,value.getJSONArray("servers").length());assertFalse(value.getJSONArray("servers").getJSONObject(0).getBoolean("enabled"));assertEquals(0,value.getJSONArray("plugins").getJSONObject(0).getJSONArray("skills").length());}
 @Test public void repositoryUrlsAllowOnlyExplicitGitHubDownloadOrigins()throws Exception{assertEquals("https://api.github.com/repos/example/repository/zipball",ExtensionImports.repositoryArchive("https://github.com/example/repository").toString());assertEquals("https://github.com/example/repository/archive/refs/heads/main.zip",ExtensionImports.repositoryArchive("https://github.com/example/repository/archive/refs/heads/main.zip").toString());for(String url:new String[]{"http://github.com/example/repository","https://github.com.evil.test/example/repository","https://user:password@github.com/example/repository","file:///secret","https://github.com/example/repository/tree/unknown"})try{ExtensionImports.repositoryArchive(url);fail(url);}catch(Exception expected){}assertFalse(ExtensionImports.downloadHost(new java.net.URL("https://unrelated.test/file.zip")));}
}
